mapper.select:
/* 요금제 약정기간 조회 : MspMapper.selectMspSaleAgrmMst :: 해당정책코드에 해당하는 약정개월정보(무약정 포함) 리스트 조회 */ SELECT RA.AGRM_TRM
FROM MSP_SALE_AGRM_MST RA WHERE 1=1
AND RA.SALE_PLCY_CD = #{salePlcyCd}
ORDER BY RA.AGRM_TRM

/* 휴대폰 할부개월 조회 : AppformMapper.selectModelMonthlyList */ SELECT INST_NOM AS MODEL_MONTHLY FROM ORG_INST_NOM_MST WHERE 1=1
AND SALE_PLCY_CD = #{salePlcyCd}
GROUP BY INST_NOM ORDER BY INST_NOM

/* 판매정책조회 : MspMapper.findMspSaleOrgnMst */ SELECT PL.SALE_PLCY_CD , --판매정책코드 PL.SALE_PLCY_NM, --판매정책명 PL.SALE_STRT_DTTM, --판매시작일시 PL.SALE_END_DTTM, --판매종료일시 PL.PLCY_TYPE_CD, --정책유형코드 M:오프라인, O:온라인 PL.ORGN_TYPE, --조직유형 PL.PLCY_SCTN_CD, --정책구분코드 01:단말, 02:USIM PL.PRDT_SCTN_CD, --제품구분코 02:3G, 03:LTE PL.APPL_SCTN_CD, --적용구분코드 O:개통일, R:접수일 PL.INST_RATE, --할부이자율 PL.NEW_YN, --신규여부 PL.MNP_YN, --번호이동여부 PL.HCN_YN, --기변여부 PL.HDN_YN, --우수기변여부 PL.SPRT_TP, --할인유형 (SELECT DTL_CD_NM FROM NMCP_CD_DTL@DL_MCP WHERE CD_GROUP_ID='F002' AND USE_YN='Y' AND PL.SPRT_TP=DTL_CD) AS SPRT_NM, --할인유형명 ORG.ORGN_ID, --조직 PRDT.PRDT_ID -- 단말아이디 ,PL.CNFM_YN --확정여부 ,PL.CNFM_ID --확정자ID ,PL.CNFM_DTTM --확정일시 ,PL.REGST_ID --등록자ID ,PL.REGST_DTTM --등록일시 ,PL.RVISN_ID --수정자ID ,PL.RVISN_DTTM --수정일시 FROM MSP_SALE_PLCY_MST PL, MSP_SALE_ORGN_MST ORG, MSP_SALE_PRDT_MST PRDT WHERE PL.CNFM_YN='Y' -- 결제 YN (필수) AND PL.SALE_PLCY_CD = ORG.SALE_PLCY_CD AND PL.SALE_PLCY_CD = PRDT.SALE_PLCY_CD AND ORG.SALE_PLCY_cD = PRDT.SALE_PLCY_CD AND TO_CHAR(SYSDATE,'yyyymmddhh24miss') BETWEEN PL.SALE_STRT_DTTM AND PL.SALE_END_DTTM --판매기간 (필수) AND PL.PLCY_TYPE_CD = #{plcyTypeCd} -- 온라인:O , 오프라인:M , 직영온라인 : D AND PL.PLCY_SCTN_CD = #{reqBuyTypeCd.rateType} -- 01:단말,02:유심 AND ORG.ORGN_ID = #{orgnId} -- 조직코드
AND PL.PRDT_SCTN_CD = #{prdtSctnCd} -- LTE,3G
AND PRDT.PRDT_ID = #{prdtId} -- 단말기ID (자급제인 경우는 SKIP 처리)
AND PL.SPRT_TP = #{sprtTp} -- KD:단말할인,PM:요금할인
AND PL.SALE_PLCY_CD = #{salePlcyCd}

/*MspMapper.listMspSalePrdtMstBySalePlcyCd 정책에 해당하는 상품의 상세정보를 가져온다.*/
/* 휴대폰 목록 조회 PhoneMapper.listPhoneProdBasForFrontOneQuery */ SELECT A.PROD_ID, -- 상품 아이디 --A.PROD_CTG_ID, --상품분류아이디 (lte,3g) A.PROD_NM AS PROD_NM, --상품명 A.MAKR_CD, --제조사코드 A.RPRS_PRDT_ID AS MODEL_ID, --대표모델ID A.SHOW_YN, --노출여부 A.SALE_YN, --판매여부 A.OFW_DATE, --출고일자 A.SNTY_OS, --단말기OS A.SNTY_PROD_NM, --단말기명 A.SNTY_COLOR, --단말기색상 A.SNTY_MAKER, --단말기제조사/브랜드명 A.SNTY_MODEL_ID AS REQ_MODEL_NM, --단말기모델번호 B.MNFCT_NM, --제조사명 NVL(A.OFW_DATE,'') as ORDER_CRET_DT, PD_SALE.SALE_PLCY_CD, --정책코드 A.REP_RATE AS REP_RATE, --대표요금제 코드 A.AGRM_TRM_BASE -- 약정유형 ,( SELECT LISTAGG(SNTY.ATRIB_VAL_CD_1, ',') WITHIN GROUP(ORDER BY SNTY.PROD_ID) FROM NMCP_SNTY_PROD_BAS@DL_MCP SNTY WHERE SNTY.PROD_ID = A.PROD_ID AND NVL(SNTY.SDOUT_YN,'N') <> 'Y' GROUP BY SNTY.PROD_ID ) AS COLOR_CODES , ( SELECT CHA.OUT_UNIT_PRIC FROM CMN_HNDST_AMT CHA WHERE CHA.RPRS_PRDT_ID = A.RPRS_PRDT_ID AND TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') BETWEEN CHA.UNIT_PRIC_APPL_DTTM AND CHA.UNIT_PRIC_EXPR_DTTM AND ROWNUM = 1 ) AS OUT_UNIT_PRIC , ( SELECT IN_UNIT_PRIC FROM CMN_MNFCT_AMT CMN WHERE RPRS_PRDT_ID = A.RPRS_PRDT_ID AND TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') BETWEEN CMN.UNIT_PRIC_APPL_DTTM AND CMN.UNIT_PRIC_EXPR_DTTM AND ROWNUM = 1 ) AS IN_UNIT_PRIC FROM NMCP_PROD_BAS@DL_MCP A, ORG_MNFCT_MST B, NMCP_SNTY_PROD_BAS@DL_MCP SNTY, ( SELECT PRDT_ID, MAX(SALE_PLCY_CD) AS SALE_PLCY_CD FROM MSP_SALE_PRDT_MST WHERE 1=1
AND SALE_PLCY_CD IN
#{prdt.salePlcyCd}
GROUP BY PRDT_ID ) PD_SALE WHERE A.SHOW_YN ='Y' AND A.RPRS_PRDT_ID = PD_SALE.PRDT_ID AND A.SALE_YN ='Y' AND A.MAKR_CD = B.MNFCT_ID
AND SNTY.RPRS_PRDT_YN = 'Y' AND A.PROD_ID = SNTY.PROD_ID

/* 핸드폰 색상 목록 조회 AppformMapper.selectPrdtColorList */ SELECT A.PRDT_COLR_CD AS MODEL_COLOR_CD ,B.CD_DSC AS MODEL_COLOR_NM
FROM CMN_INTM_MDL A , CMN_GRP_CD_MST B WHERE A.RPRS_YN = 'N' AND A.PRDT_COLR_CD = B.CD_VAL AND B.GRP_ID = 'CMN0044'
AND A.RPRS_PRDT_ID = #{rprsPrdtId}

/* 휴대폰 용량 목록 조회 PhoneMapper.triggerSelectProdBasImgDtlList */ SELECT A.ATRIB_VAL_CD_2 AS MODEL_CAPACITY_CD ,A.ATRIB_VAL_NM_2 AS MODEL_CAPACITY_NM
FROM NMCP_SNTY_PROD_BAS@DL_MCP A , NMCP_PROD_ATRIB_VAL_DTL@DL_MCP B WHERE 1=1 AND A.ATRIB_VAL_CD_2 = A.ATRIB_VAL_CD_2 AND B.ATRIB_CD='P0'
AND A.PROD_ID = #{prodId}
GROUP BY A.PROD_ID,A.ATRIB_VAL_CD_2,A.ATRIB_VAL_NM_2

/* 요금제 목록 조회 MspMapper.listRateByOrgnInfos */ SELECT DISTINCT RATE_MST.RATE_CD, RATE_MST.RATE_NM, RATE_MST.RATE_GRP_CD, RATE_MST.PAY_CL_CD, RATE_MST.RATE_TYPE, RATE_MST.DATA_TYPE, RATE_MST.BASE_AMT, RATE_MST.FREE_CALL_CL_CD, RATE_MST.FREE_CALL_CNT, RATE_MST.NW_IN_CALL_CNT, RATE_MST.NW_OUT_CALL_CNT, RATE_MST.FREE_SMS_CNT, RATE_MST.FREE_DATA_CNT, RATE_MST.RMK, RATE_MST.ONLINE_TYPE_CD, RATE_MST.AL_FLAG,
RATE_MST.SERVICE_TYPE, RATE_MST.JEHU_PROD_TYPE, --요금제제휴처 (SELECT DTL_CD_NM FROM NMCP_CD_DTL@DL_MCP WHERE CD_GROUP_ID='JehuProdType' AND DTL_CD=RATE_MST.JEHU_PROD_TYPE AND ROWNUM=1) AS JEHU_PROD_NM, -- 요금제 제휴처명 PLCY.SPRT_TP, PLCY.PLCY_SCTN_CD, --정책구분코드 01:단말, 02:USIM PLCY.PRDT_SCTN_CD, --제품구분코드 >> LTE5G, 5G, 3G, LTE PLCY.PLCY_TYPE_CD --CMN0050 정책유형코드 : W 도매 FROM MSP_SALE_ORGN_MST ORGN, MSP_SALE_PLCY_MST PLCY, MSP_SALE_RATE_MST RATE, MSP_RATE_MST RATE_MST
WHERE 1=1 AND ORGN.SALE_PLCY_CD = PLCY.SALE_PLCY_CD AND PLCY.SALE_PLCY_CD = RATE.SALE_PLCY_CD AND RATE_MST.RATE_CD = RATE.RATE_CD AND TO_CHAR(SYSDATE,'yyyymmddhh24miss') BETWEEN PLCY.SALE_STRT_DTTM AND PLCY.SALE_END_DTTM /* 판매기간 */ AND PLCY.CNFM_YN = 'Y' AND PLCY.PLCY_TYPE_CD = #{plcyTypeCd} AND RATE_MST.PAY_CL_CD = #{payClCd} AND ORGN.ORGN_ID = #{orgnId} /* 조직코드 */ AND RATE_MST.SERVICE_TYPE = #{serviceType} AND PLCY.PLCY_SCTN_CD = #{reqBuyTypeCd.rateType} AND RATE_MST.RATE_TYPE = #{reqBuyTypeCd.rateType}
AND ORGN.SALE_PLCY_CD = #{salePlcyCd} /* 판매정책코드 */
AND PLCY.SPRT_TP = #{sprtTp} /* 할인유형 : KD, PM */
AND PLCY.PRDT_SCTN_CD = #{prdtSctnCd} /* 02 : LTE, 03 : 3G */
AND RATE_MST.RATE_CD IN
#{rate.prodId}
ORDER BY RATE_MST.RATE_NM

/** 부가서비스 상세 정보 조회 **/ SELECT A.RATE_CD, A.RATE_NM, A.BASE_AMT FROM MSP_RATE_MST A LEFT JOIN MSP_SALE_RATE_MST B ON A.RATE_CD = B.RATE_CD WHERE 1=1 AND A.SERVICE_TYPE = 'R' AND B.SALE_PLCY_CD IS NULL
AND A.RATE_CD IN
#{addRate.prodId}
